437: func (c *RuntimeCoordinator) dispatchGate(ctx context.Context, route RuntimeCoordinatorRoute, runID, lease string, epoch int64) (*sql.Tx, Object, Object, error) {
438: 	tx, e := c.service.DB.BeginTx(ctx, nil)
439: 	if e != nil {
440: 		return nil, nil, nil, e
441: 	}
442: 	fail := func(e error) (*sql.Tx, Object, Object, error) { tx.Rollback(); return nil, nil, nil, e }
443: 	if e = resourceWriteLock(tx); e != nil {
444: 		return fail(e)
445: 	}
446: 	if _, e = resourcePrincipal(tx, c.config.SchedulerToken, route.ProjectID, "SCHEDULER"); e != nil {
447: 		return fail(e)
448: 	}
449: 	executor, e := authenticate(tx, route.ExecutorToken)
450: 	if e != nil {
451: 		return fail(e)
452: 	}
453: 	run, e := currentRun(tx, executor, route.ProjectID, runID)
454: 	if e != nil {
