462: 	}
463: 	dispatch, e := runtimeDispatch(tx, route.ProjectID, runID, epoch)
464: 	if e != nil {
465: 		return fail(e)
466: 	}
467: 	task, e := load(tx, route.ProjectID, "Task", Str(run, "task_id"))
468: 	if e != nil {
469: 		return fail(e)
470: 	}
471: 	if task["task_type"] == "mu_turn" {
472: 		if e = c.sessionTaskRoute(tx, route.ProjectID, task, route.RuntimeID); e != nil {
