972: func (c *RuntimeCoordinator) Recover(ctx context.Context) error {
973: 	rows, e := c.service.DB.QueryContext(ctx, "SELECT project,run,epoch,dispatch_key,manifest_hash,journal_locator FROM runtime_dispatches")
974: 	if e != nil {
975: 		return e
976: 	}
977: 	type fact struct {
978: 		project, run, key, hash, locator string
979: 		epoch                            int64
980: 	}
981: 	facts := []fact{}
982: 	for rows.Next() {
983: 		var f fact
984: 		if e = rows.Scan(&f.project, &f.run, &f.epoch, &f.key, &f.hash, &f.locator); e != nil {
985: 			rows.Close()
986: 			return e
987: 		}
988: 		facts = append(facts, f)
989: 	}
990: 	e = rows.Err()
991: 	rows.Close()
992: 	if e != nil {
993: 		return e
994: 	}
995: 	for _, f := range facts {
996: 		if f.locator == "" || f.locator != f.key || !filepath.IsLocal(f.locator) {
997: 			if e = c.markUnknown(ctx, f.project, f.run, f.epoch, "no acknowledged worker journal"); e != nil {
998: 				return e
999: 			}
1000: 			continue
1001: 		}
1002: 		directory := filepath.Join(c.config.DataRoot, "runtime-dispatches", f.locator)
