1004: 		if e = c.recoverEffects(ctx, f.project, f.run, directory, f.epoch); e != nil {
1005: 			return e
1006: 		}
1007: 		if e = c.recoverCheckpoints(ctx, f.project, f.run, directory, f.epoch); e != nil {
