172: 	if err := c.recoverClientQueue(ctx, project, runID, epoch, j); err != nil {
173: 		return err
174: 	}
175: 	if e := c.ingestObservation(ctx, project, runID, epoch, j); e != nil {
176: 		return e
177: 	}
178: 	observation, e := j.Observation()
179: 	if e != nil {
180: 		return e
