189: 			return errors.New("historical output changed after terminal validation")
190: 		}
191: 		files = append(files, struct {
192: 			kind string
193: 			raw  []byte
194: 		}{"REPORT", raw})
195: 	}
196: 	tx, e := c.service.DB.BeginTx(ctx, nil)
197: 	if e != nil {
198: 		return e
199: 	}
200: 	defer tx.Rollback()
201: 	if e = resourceWriteLock(tx); e != nil {
202: 		return e
203: 	}
204: 	dispatch, e := runtimeDispatch(tx, project, runID, epoch)
