209: 	var log Object
210: 	for _, f := range files {
211: 		artifact, e := c.recoverArtifact(tx, project, dispatch, f.raw, f.kind)
212: 		if e != nil {
213: 			return e
214: 		}
215: 		if f.kind == "LOG" {
216: 			log = artifact
217: 		} else {
218: 			ids = append(ids, artifact["id"])
219: 		}
220: 	}
