222: 	// authority has moved on. A separate transaction decides current completion.
223: 	if e = tx.Commit(); e != nil {
224: 		return e
225: 	}
226: 	tx, e = c.service.DB.BeginTx(ctx, nil)
227: 	if e != nil {
228: 		return e
229: 	}
230: 	defer tx.Rollback()
231: 	if e = resourceWriteLock(tx); e != nil {
232: 		return e
233: 	}
234: 	run, e := load(tx, project, "Run", runID)
235: 	if e != nil {
236: 		return e
237: 	}
